import { Suspense, lazy } from 'react'
import Header from './components/layout/Header'
import Sidebar from './components/layout/Sidebar'
import useAppStore from './store/appStore'

// Lazy-loaded views
const UnitConversion   = lazy(() => import('./views/UnitConversion'))
const CurrencyExchange = lazy(() => import('./views/CurrencyExchange'))
const RebarArea        = lazy(() => import('./views/RebarArea'))
const SlabView         = lazy(() => import('./views/MinReinf/SlabView'))
const BeamView         = lazy(() => import('./views/MinReinf/BeamView'))
const ColumnView       = lazy(() => import('./views/MinReinf/ColumnView'))
const WallView         = lazy(() => import('./views/MinReinf/WallView'))
const BoltStrength     = lazy(() => import('./views/BoltStrength'))
const WeldStrength     = lazy(() => import('./views/WeldStrength'))
const StructuralReport = lazy(() => import('./views/StructuralReport'))
const HShape           = lazy(() => import('./views/HShape'))
const WShape           = lazy(() => import('./views/WShape'))
const SnowDrift        = lazy(() => import('./views/SnowDrift'))

const VIEW_MAP = {
  'unit-conversion':   UnitConversion,
  'currency-exchange': CurrencyExchange,
  'rebar-area':        RebarArea,
  'min-reinf-slab':    SlabView,
  'min-reinf-beam':    BeamView,
  'min-reinf-column':  ColumnView,
  'min-reinf-wall':    WallView,
  'bolt-strength':     BoltStrength,
  'weld-strength':     WeldStrength,
  'struct-report':     StructuralReport,
  'hs-shape':          HShape,
  'steel-w':           WShape,
  'snow-drift':        SnowDrift,
}

function Loading() {
  return (
    <div className="flex items-center justify-center h-48" style={{ color: 'var(--tx-muted)' }}>
      <div style={{
        width: 28, height: 28,
        border: '3px solid var(--bd-subtle)',
        borderTopColor: 'var(--ac-main)',
        borderRadius: '50%',
        animation: 'spin 0.9s linear infinite',
      }} />
    </div>
  )
}

export default function App() {
  const activeView = useAppStore(s => s.activeView)
  const ActiveComponent = VIEW_MAP[activeView]

  return (
    <div style={{ minHeight: '100vh', background: 'var(--bg-base)' }}>
      <style>{`@keyframes spin { to { transform: rotate(360deg) } }`}</style>
      <Header />
      <div style={{ display: 'flex' }}>
        <Sidebar />
        <main style={{ flex: 1, padding: '32px 36px', minWidth: 0 }}>
          <Suspense fallback={<Loading />}>
            {ActiveComponent ? <ActiveComponent /> : (
              <p style={{ color: 'var(--tx-muted)' }}>View not found: {activeView}</p>
            )}
          </Suspense>
        </main>
      </div>
    </div>
  )
}
