import { useState } from 'react'
import useAppStore, { VIEWS } from '../../store/appStore'

export default function Sidebar() {
  const { activeView, setActiveView } = useAppStore()
  const [expanded, setExpanded] = useState({ 'min-reinforcement': true })

  function handleClick(view) {
    if (view.children) {
      setExpanded(e => ({ ...e, [view.id]: !e[view.id] }))
      setActiveView(view.children[0].id)
    } else {
      setActiveView(view.id)
    }
  }

  const isParentActive = (view) =>
    view.children?.some(c => c.id === activeView)

  return (
    <nav
      className="sidebar overflow-y-auto py-4"
      style={{
        background: 'var(--bg-surface)',
        borderRight: '1px solid var(--bd-subtle)',
        width: 220,
        minHeight: 'calc(100vh - 64px)',
        position: 'sticky',
        top: 64,
        flexShrink: 0,
      }}
    >
      {VIEWS.map(view => (
        <div key={view.id}>
          <button
            onClick={() => handleClick(view)}
            className="menu-item w-full text-left px-4 py-2.5 text-xs font-semibold flex items-center justify-between"
            style={{
              borderLeft: `3px solid ${
                activeView === view.id || isParentActive(view)
                  ? 'var(--ac-main)'
                  : 'transparent'
              }`,
              background:
                activeView === view.id || isParentActive(view)
                  ? 'var(--bg-active)'
                  : 'transparent',
              color:
                activeView === view.id || isParentActive(view)
                  ? 'var(--ac-main)'
                  : 'var(--tx-secondary)',
              transition: 'all 0.15s',
            }}
          >
            <span>{view.label}</span>
            {view.children && (
              <span style={{ fontSize: 10 }}>
                {expanded[view.id] ? '▲' : '▼'}
              </span>
            )}
          </button>

          {view.children && expanded[view.id] && (
            <div>
              {view.children.map(child => (
                <button
                  key={child.id}
                  onClick={() => setActiveView(child.id)}
                  className="w-full text-left py-2 text-xs"
                  style={{
                    paddingLeft: 36,
                    borderLeft: `3px solid ${
                      activeView === child.id ? 'var(--ac-main)' : 'transparent'
                    }`,
                    background:
                      activeView === child.id ? 'var(--bg-active)' : 'transparent',
                    color:
                      activeView === child.id
                        ? 'var(--ac-main)'
                        : 'var(--tx-secondary)',
                    fontWeight: activeView === child.id ? 700 : 400,
                    transition: 'all 0.15s',
                  }}
                >
                  {child.label}
                </button>
              ))}
            </div>
          )}
        </div>
      ))}
    </nav>
  )
}
